def _paths(svg):
    return re.findall(r'<path d="([^"]*)"', svg)


def _pts(d):
    return [(float(a), float(b)) for a, b in re.findall(r"[ML](-?[\d.]+) (-?[\d.]+)", d)]


def test_globe_is_a_complete_server_side_svg_with_graticule_pins_and_arcs():
    html = _py_html(GLOBE)
    svg = _svg(html)
    assert svg.startswith("<svg") and 'aria-hidden="true"' in svg
    cx = cy = 150.0
    R = 300 * 0.42
    front = _pts(_paths(svg)[1] if False else re.findall(r'<path d="([^"]*)" fill="none" style="stroke:#10b981" stroke-opacity="0.7"', svg)[0])
    assert len(front) > 200, "the d3 graticule is drawn"
    for x, y in front:
        assert math.hypot(x - cx, y - cy) <= R + 0.02, (x, y)  # clipped at the horizon
    assert 'style="stroke:#f59e0b"' in svg  # the great-circle arc
    assert 'style="fill:#ef4444"' in svg and ">Paris</text>" in svg and ">Sydney</text>" in svg
    # no CDN, no D3 at runtime
    assert "<script src" not in html and "cdn" not in html.lower() and "d3js" not in html and "d3." not in html


