def test_globe_static_svg_is_centred_on_the_pins_like_d3_rotate():
    """Paris and Sydney are 16000 km apart: the settled view is centred on their centroid, in d3's rotate([-lon, -lat])."""
    foc = wa._geo_focus({"dots": GLOBE["dots"][:2], "arcs": GLOBE["arcs"]})
    p = wa._geo_ortho([-foc[0], -foc[1], 0], 126, 150, 150)
    v = p(foc[0], foc[1])
    _near(v[0], 150); _near(v[1], 150); _near(v[2], 1)


