def test_radar_links_are_great_circles_split_at_the_antimeridian():
    svg = _svg(_py_html(RADAR))
    link = re.search(r'<path class="gmrl" d="([^"]*)"', svg).group(1)
    assert link.count("M") >= 4, "Tokyo-Honolulu crosses the antimeridian: its line is cut, not drawn across the map"
    for sub in link.split("M")[1:]:
        xs = [p[0] for p in _pts("M" + sub)]
        assert max(xs) - min(xs) < 400, "no segment spans the world"


